CREATE SEQUENCE users_seq INCREMENT BY 1;
CREATE TABLE users(id integer PRIMARY KEY,username varchar(40) NOT NULL UNIQUE,password varchar(255) NOT NULL);
CREATE TABLE product(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255),description varchar(255),brand varchar(255),price numeric(38,2),category varchar(255),release_date timestamp(6),product_available boolean NOT NULL,stock_quantity integer NOT NULL,image_name varchar(255),image_type varchar(255),image_data oid);
CREATE TABLE orders(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id varchar(255) UNIQUE,owner_username varchar(255),customer_name varchar(255),email varchar(255),status varchar(255),order_date date);
CREATE TABLE order_item(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id bigint REFERENCES product(id),quantity integer NOT NULL,total_price numeric(38,2),order_id bigint REFERENCES orders(id));
